# ------------------------------------------------------------------ 4. traps
print("\n=== NAMING TRAP: code-name 'ColdSite' ===")
name_rx = re.compile(r"cold[\s_-]?site", re.I); bad = 0
for i in S:
    for w in ("vis", "notes", "alt"):
        for m in name_rx.finditer(S[i][w]):
            ctx = S[i][w][max(0, m.start() - 60):m.end() + 40].replace("\n", " ")
            allowed = i == 1 and (("NAMING NOTE" in S[i]["vis"] and w == "vis") or w == "notes")
            print(f"  slide {i} {w:5} {'ALLOWED (naming note)' if allowed else 'FAIL'} ...{ctx}...")
            if not allowed: bad += 1; results.append(("FAIL", i, "code-name on a slide", ctx))
zf = __import__("zipfile").ZipFile(DECK); media_hits = [n for n in zf.namelist() if n.startswith("ppt/slides/") and n.endswith(".xml") and name_rx.search(zf.read(n).decode("utf8", "ignore")) and n != "ppt/slides/slide1.xml"]
print(f"  slide XML parts other than slide 1 containing the code-name: {media_hits or 'none'}")
if media_hits: bad += 1; results.append(("FAIL", 0, "code-name in slide XML", str(media_hits)))
draft = open("paper/v2/INSTRUCTOR_DRAFT.md", encoding="utf-8").read(); prose = re.sub(r"<!--.*?-->", "", draft, flags=re.S)
code_spans = [(m.start(), m.end()) for m in re.finditer(r"`[^`]*`", prose)]
dm = [(prose[max(0, m.start() - 50):m.end() + 40].replace("\n", " "), any(a <= m.start() < b for a, b in code_spans)) for m in name_rx.finditer(prose)]
print(f"  draft prose (comments stripped): {len(dm)} occurrence(s), {sum(not c for _, c in dm)} in running prose, {sum(c for _, c in dm)} inside a `code span` (a file path)")
for c, in_code in dm: print(f"    {'code path' if in_code else 'PROSE    '} ...{c}...")
if sum(not c for _, c in dm) != 1: results.append(("WARN", 0, "draft prose mentions of the code-name", "running prose should contain exactly the one naming sentence"))
for c, in_code in dm:
    if in_code: results.append(("WARN", 0, "draft cites a file path containing the code-name", c))
files = [p for p in glob.glob("results/**/*", recursive=True) if os.path.isfile(p) and p.endswith((".md", ".csv", ".txt", ".json", ".log"))]
hit = {p: len(name_rx.findall(open(p, encoding="utf-8", errors="ignore").read())) for p in files}; hit = {p: n for p, n in hit.items() if n}
print(f"  results/: {len(hit)} of {len(files)} text files contain the name (raw logs, tables and JSON keys); files the slides or draft cite as sources:")
cited = set(re.findall(r"(results/[\w./\-]+?\.(?:md|csv|txt|json))", S[1]["vis"] + "".join(S[i]["vis"] + S[i]["notes"] for i in S) + draft))
for p in sorted(cited & set(hit)): print(f"    WARN cited file exposes the code-name: {p} ({hit[p]}x)"); results.append(("WARN", 0, "cited file exposes the code-name", p))
print("\n=== OVERCLAIM TRAP ===")
over = re.compile(r"\bSOTA\b|state[- ]of[- ]the[- ]art|novel architecture|new (?:model|architecture|method)|outperform\w*|best[- ]in[- ]class|breakthrough|first to\b|unprecedented|revolution\w*|superior to|beats? (?:the )?(?:baseline|published)", re.I)
n_over = 0
for label, text in [(f"slide {i} {w}", S[i][w]) for i in S for w in ("vis", "notes")] + [("draft prose", prose)]:
    for m in over.finditer(text):
        ctx = text[max(0, m.start() - 40):m.end() + 30].replace("\n", " "); neg = bool(re.search(r"(not an?|no|never|instead of|rather than( an?)?|nor)\s+$", text[max(0, m.start() - 20):m.start()], re.I))
        print(f"  {label:14} {'NEGATED (ok)' if neg else 'FLAG':12} ...{ctx}..."); n_over += not neg
        if not neg: results.append(("FAIL", 0, "overclaim vocabulary", ctx))
