# ------------------------------------------------------------------ 5. accounting
print("\n=== NUMERIC TOKEN ACCOUNTING (visible slide text) ===")
tok = re.compile(r"(?<![\w.])[+−-]?\d[\d,]*(?:\.\d+)?")
unreg = []
for i in S:
    text = S[i]["vis"]; spans = [(a, b) for w, a, b in covered[i] if w == "vis"]
    for m in tok.finditer(text):
        if any(a <= m.start() < b for a, b in spans): continue
        pre = text[max(0, m.start() - 16):m.start()]; t = m.group(0).rstrip(",")
        if re.match(r"\d+ / 10\b", text[m.start():]) or pre.endswith("/ "): continue                      # page numbers "n / 10"
        if re.search(r"(Figure|Fig\.|Box|§|BRIEFING ·|SEPTEMBER|draft §|Table|Image|RESULT|@|BOX|seed\{)\s*$", pre) or re.fullmatch(r"(19|20)\d\d", t): continue   # labels, image indices, years, precision@10
        if re.fullmatch(r"\d(,\d)*", t) and re.search(r"seeds? \d?[{]?$|\{[\d,]*$", pre + t): continue     # 'seeds 1–3', 'seed{1,2,3}'
        if t == "0.05" and pre.rstrip().endswith("="): continue                                             # the conventional alpha, stated as such
        if t == "95" and text[m.end():m.end() + 1] == "%": continue                                         # interval level
        unreg.append((i, t, text[max(0, m.start() - 30):m.end() + 25].replace("\n", " ")))
print(f"  numeric tokens not claimed by any check: {len(unreg)}")
for i, t, c in unreg: print(f"    slide {i:>2} '{t}' ...{c}...")

